function localMatrix(n,f){const p=parts[n],v=partTransformValues(n,f),pv=p.pivot;let m=M.T(v.pos[0],v.pos[1],v.pos[2]);m=M.mul(m,M.T(...pv));m=M.mul(m,M.Rz(rad(v.rot[2])));m=M.mul(m,M.Ry(rad(v.rot[1])));m=M.mul(m,M.Rx(rad(v.rot[0])));m=M.mul(m,M.S(...v.scale));m=M.mul(m,M.T(-pv[0],-pv[1],-pv[2]));return m;}
