function setFrame(f){state.frame=clamp(Math.round(f),0,state.duration);ensureTimelineFrameVisible(state.frame);$('#frameInput').value=state.frame;$('#framePill').textContent='F '+state.frame;syncInspector();timelineDraw();curveDraw();render();}

