const solidProg=program(`#version 300 es
in vec3 aPos;in vec3 aNormal;in vec2 aUv;uniform mat4 uModel;uniform mat4 uVP;out vec3 vN;out vec3 vW;out vec2 vUv;void main(){vec4 w=uModel*vec4(aPos,1.0);vW=w.xyz;vN=normalize(mat3(uModel)*aNormal);vUv=aUv;gl_Position=uVP*w;}`,
`#version 300 es
precision highp float;in vec3 vN;in vec3 vW;in vec2 vUv;uniform vec3 uDiffuse,uAmbient,uSpecular,uLightDir,uEye,uTint;uniform float uKa,uKd,uKs,uShine,uAmbientI,uLightI,uSpecI,uAlpha,uTintMix,uBrightness;uniform sampler2D uTex;uniform int uHasTex;out vec4 outColor;void main(){vec3 n=normalize(vN);if(!gl_FrontFacing)n=-n;vec3 l=normalize(uLightDir),v=normalize(uEye-vW);float ndl=max(dot(n,l),0.0);float facing=max(dot(n,v),0.0);float ambient=0.22+0.46*uAmbientI;float diffuse=uLightI*(0.10+0.90*ndl);vec3 h=normalize(l+v);float sp=pow(max(dot(n,h),0.0),max(4.0,uShine));vec4 texel=uHasTex==1?texture(uTex,vUv):vec4(1.0);vec3 base=uDiffuse*texel.rgb;vec3 c=base*(ambient+diffuse*uKd)+uSpecular*(uKs*uSpecI*sp*0.34);c+=base*(0.035*facing);float shade=max(max(c.r,c.g),c.b);vec3 colorized=uTint*shade;c=mix(c,colorized,uTintMix);c*=uBrightness;outColor=vec4(clamp(c,0.0,1.0),uAlpha*texel.a);}`);
