const su={};['uModel','uVP','uDiffuse','uAmbient','uSpecular','uLightDir','uEye','uTint','uKa','uKd','uKs','uShine','uAmbientI','uLightI','uSpecI','uAlpha','uTintMix','uBrightness','uTex','uHasTex'].forEach(n=>su[n]=gl.getUniformLocation(solidProg,n));
const ll={aPos:gl.getAttribLocation(lineProg,'aPos')},lu={uModel:gl.getUniformLocation(lineProg,'uModel'),uVP:gl.getUniformLocation(lineProg,'uVP'),uColor:gl.getUniformLocation(lineProg,'uColor')};
const pl={aPos:gl.getAttribLocation(pickProg,'aPos')},pu={uModel:gl.getUniformLocation(pickProg,'uModel'),uVP:gl.getUniformLocation(pickProg,'uVP'),uId:gl.getUniformLocation(pickProg,'uId')};
let pickFbo=gl.createFramebuffer(),pickTex=gl.createTexture(),pickDepth=gl.createRenderbuffer(),pickW=0,pickH=0;
function resizePickBuffer(w,h){if(w===pickW&&h===pickH)return;pickW=w;pickH=h;gl.bindTexture(gl.TEXTURE_2D,pickTex);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.NEAREST);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.NEAREST);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA8,w,h,0,gl.RGBA,gl.UNSIGNED_BYTE,null);gl.bindRenderbuffer(gl.RENDERBUFFER,pickDepth);gl.renderbufferStorage(gl.RENDERBUFFER,gl.DEPTH_COMPONENT24,w,h);gl.bindFramebuffer(gl.FRAMEBUFFER,pickFbo);gl.framebufferTexture2D(gl.FRAMEBUFFER,gl.COLOR_ATTACHMENT0,gl.TEXTURE_2D,pickTex,0);gl.framebufferRenderbuffer(gl.FRAMEBUFFER,gl.DEPTH_ATTACHMENT,gl.RENDERBUFFER,pickDepth);gl.bindFramebuffer(gl.FRAMEBUFFER,null);}
