for(const p of Object.values(parts))buildGpuForPart(p);
const defaultMat={diffuse:[.75,.75,.75],ambient:[.75,.75,.75],specular:[1,1,1],ka:.3,kd:.7,ks:.2,shininess:32,alpha:1};
const runtimeMaterials=deepClone(model.materials||{});
const material=n=>runtimeMaterials[n]||defaultMat;
