function cameraBasis(){const cm=cameraMatrices(),forward=V.norm(V.sub(state.camera.target,cm.eye)),right=V.norm(V.cross(forward,[0,1,0])),up=V.norm(V.cross(right,forward));return {forward,right,up};}
