   if(state.tool==='rotate'&&a>=0){let delta=gizmoDrag.accumDeg||0;if(gizmoDrag.lastVec){const hit=rayPlanePoint(x,y,gizmoDrag.h.pivotWorld,gizmoDrag.h.axisWorld);if(hit){const cur=V.norm(V.sub(hit,gizmoDrag.h.pivotWorld)),cross=V.cross(gizmoDrag.lastVec,cur),step=Math.atan2(V.dot(gizmoDrag.h.axisWorld,cross),clamp(V.dot(gizmoDrag.lastVec,cur),-1,1));if(Number.isFinite(step)&&Math.abs(step)<Math.PI*.75){delta+=deg(step);gizmoDrag.accumDeg=delta;gizmoDrag.lastVec=cur;}}}else{const ang=Math.atan2(y-gizmoDrag.center[1],x-gizmoDrag.center[0]);let da=ang-(gizmoDrag.startAng||0);while(da>Math.PI)da-=Math.PI*2;while(da<-Math.PI)da+=Math.PI*2;delta=deg(da);}const vals=[...gizmoDrag.start.rot];vals[a]=gizmoDrag.start.rot[a]+delta;if(state.autoKey)keyTransformChannel(n,'rot',vals,gizmoDrag.start.rot,true);else p.base.rot=[...vals];}
