function applyScrubFrame(f){state.frame=clamp(Math.round(f),0,state.duration);$('#frameInput').value=state.frame;$('#framePill').textContent='F '+state.frame;syncInspector();timelineDraw();render();}
function queueScrub(clientX){const p={x:clientX-tl.getBoundingClientRect().left,width:tl.getBoundingClientRect().width};pendingScrubFrame=frameFromTimelineX(p.x,p.width);if(scrubRAF)return;scrubRAF=requestAnimationFrame(()=>{scrubRAF=0;applyScrubFrame(pendingScrubFrame);});}
function beginTimelinePointer(e){if(e.button!==0&&e.button!==1)return;tl.focus({preventScroll:true});const p=timelinePoint(e),row=timelineRowAt(p.y),add=e.ctrlKey||e.metaKey||e.shiftKey;if(e.button===1||e.altKey){state.timelineDrag={mode:'panTime',startX:p.x,startView:state.timelineView.start};timelinePointer=e.pointerId;tl.setPointerCapture?.(e.pointerId);tl.classList.add('panningTime');e.preventDefault();return;}if(p.y<TL.ruler){state.timelineDrag={mode:'scrub'};timelinePointer=e.pointerId;tl.setPointerCapture?.(e.pointerId);tl.classList.add('scrubbing');queueScrub(e.clientX);e.preventDefault();return;}if(p.x<TL.left){if(row?.type==='part'){if(p.x<21){state.timelineCollapsed[row.part]=!state.timelineCollapsed[row.part];timelineDraw();}else selectPart(row.part);}else if(row?.part)selectPart(row.part);e.preventDefault();return;}const hit=timelineKeyAt(p.x,p.y);timelinePointer=e.pointerId;tl.setPointerCapture?.(e.pointerId);if(hit){if(state.selected!==hit.part)selectPart(hit.part);const tok=keyToken(hit.part,hit.channel,hit.frame);if(add){if((e.ctrlKey||e.metaKey)&&state.timelineSelection.has(tok))state.timelineSelection.delete(tok);else state.timelineSelection.add(tok);}else if(!state.timelineSelection.has(tok)){state.timelineSelection.clear();state.timelineSelection.add(tok);}setFrame(hit.frame);state.timelineDrag={mode:'keys',startX:p.x,startY:p.y,delta:0,moved:false};tl.classList.add('keyDragging');timelineDraw();}
 else{const base=new Set(add?state.timelineSelection:[]);if(!add)state.timelineSelection.clear();state.timelineDrag={mode:'box',startX:p.x,startY:p.y,x:p.x,y:p.y,current:{x:p.x,y:p.y},base,moved:false,clickFrame:frameFromTimelineX(p.x,p.width)};tl.classList.add('boxSelecting');timelineDraw();}e.preventDefault();}
function moveTimelinePointer(e){if(timelinePointer!=null&&e.pointerId!==timelinePointer)return;const drag=state.timelineDrag;if(!drag)return;if(drag.mode==='scrub'){queueScrub(e.clientX);return;}const p=timelinePoint(e);if(drag.mode==='panTime'){const dx=p.x-drag.startX;state.timelineView.start=clamp(drag.startView-dx/state.timelineView.pxPerFrame,0,timelineMaxStart(p.width));timelineDraw();return;}if(drag.mode==='keys'){const raw=Math.round((p.x-drag.startX)/state.timelineView.pxPerFrame),entries=selectedKeyEntries();if(entries.length){const mn=Math.min(...entries.map(q=>q.frame)),mx=Math.max(...entries.map(q=>q.frame));drag.delta=clamp(raw,-mn,state.duration-mx);}drag.moved=drag.moved||Math.hypot(p.x-drag.startX,p.y-drag.startY)>3;timelineDraw();}
 else if(drag.mode==='box'){drag.current={x:p.x,y:p.y};drag.moved=drag.moved||Math.hypot(p.x-drag.startX,p.y-drag.startY)>4;if(drag.moved){const x1=Math.min(drag.startX,p.x),x2=Math.max(drag.startX,p.x),y1=Math.min(drag.startY,p.y),y2=Math.max(drag.startY,p.y),next=new Set(drag.base);for(const h of timelineKeyHits)if(h.x>=x1&&h.x<=x2&&h.y>=y1&&h.y<=y2)next.add(keyToken(h.part,h.channel,h.frame));state.timelineSelection=next;}timelineDraw();}}
function endTimelinePointer(e){if(timelinePointer!=null&&e&&e.pointerId!==timelinePointer)return;const drag=state.timelineDrag;if(!drag)return;if(drag.mode==='scrub'){if(scrubRAF){cancelAnimationFrame(scrubRAF);scrubRAF=0;applyScrubFrame(pendingScrubFrame);}curveDraw();keyListDraw();}else if(drag.mode==='panTime'){state.timelineDrag=null;tl.classList.remove('panningTime');timelineDraw();}
 else if(drag.mode==='keys'){const d=drag.delta||0;state.timelineDrag=null;tl.classList.remove('keyDragging');if(drag.moved&&d)moveSelectedTimelineKeys(d);else timelineDraw();}
 else if(drag.mode==='box'){const clickFrame=drag.clickFrame,moved=drag.moved;state.timelineDrag=null;tl.classList.remove('boxSelecting');if(!moved)setFrame(clickFrame);else{updateKeySelectionUI();timelineDraw();status(`${state.timelineSelection.size} key seçildi. Sürükleyerek taşıyabilir, Ctrl+C/Ctrl+V kullanabilirsin.`);}}state.timelineDrag=null;timelinePointer=null;tl.classList.remove('scrubbing','keyDragging','boxSelecting','panningTime');}
tl.addEventListener('pointerdown',beginTimelinePointer);window.addEventListener('pointermove',moveTimelinePointer);window.addEventListener('pointerup',endTimelinePointer);window.addEventListener('pointercancel',endTimelinePointer);
if(tlr){tlr.addEventListener('pointerdown',e=>{if(e.button!==0)return;tl.focus({preventScroll:true});state.timelineDrag={mode:'scrub'};timelinePointer=e.pointerId;tlr.setPointerCapture?.(e.pointerId);tlr.classList.add('scrubbing');queueScrub(e.clientX);e.preventDefault();});window.addEventListener('pointerup',()=>tlr.classList.remove('scrubbing'));window.addEventListener('pointercancel',()=>tlr.classList.remove('scrubbing'));}
const handleTimelineWheel=e=>{if(e.shiftKey){e.preventDefault();const dy=e.deltaY||e.deltaX,fac=Math.exp(-dy*0.0025);zoomTimelineAt(e.clientX,state.timelineView.pxPerFrame*fac);}else if(Math.abs(e.deltaX)>0.5){e.preventDefault();panTimelineFrames(e.deltaX/state.timelineView.pxPerFrame);}};tl.addEventListener('wheel',handleTimelineWheel,{passive:false});if(tlr)tlr.addEventListener('wheel',handleTimelineWheel,{passive:false});
