tl.addEventListener('dblclick',e=>{const p=timelinePoint(e),row=timelineRowAt(p.y);if(row?.type==='channel'&&p.x>=TL.left&&!timelineKeyAt(p.x,p.y)){selectPart(row.part);setFrame(frameFromTimelineX(p.x,p.width));keyTransformChannel(row.part,row.channel,partTransformValues(row.part)[row.channel],null,false);const tok=keyToken(row.part,row.channel,state.frame);state.timelineSelection.clear();state.timelineSelection.add(tok);timelineDraw();status(`${row.part} • ${row.label} key eklendi.`);}});

// ---------- curve editor ----------
const curve=$('#curveCanvas');
function curveDraw(){const d=resize2D(curve),ctx=curve.getContext('2d'),w=curve.width,h=curve.height;ctx.fillStyle='#1c1f22';ctx.fillRect(0,0,w,h);const ch=$('#curveChannel').value||'rz',tr=getTrack(state.selected,ch)||[];const L=34*d,R=8*d,T=10*d,B=24*d;let vals=tr.map(k=>k.v);if(!vals.length)vals=[baseValue(state.selected,ch)-1,baseValue(state.selected,ch)+1];let mn=Math.min(...vals),mx=Math.max(...vals);if(Math.abs(mx-mn)<1e-6){mn-=1;mx+=1;}const pad=(mx-mn)*.18;mn-=pad;mx+=pad;const X=f=>L+(w-L-R)*f/Math.max(1,state.duration),Y=v=>T+(h-T-B)*(1-(v-mn)/(mx-mn));ctx.strokeStyle='#30353a';ctx.lineWidth=1;for(let i=0;i<=5;i++){const y=T+(h-T-B)*i/5;ctx.beginPath();ctx.moveTo(L,y);ctx.lineTo(w-R,y);ctx.stroke();ctx.fillStyle='#8f969d';ctx.font=`${8*d}px Segoe UI`;ctx.fillText((mx-(mx-mn)*i/5).toFixed(1),2*d,y+3*d);}ctx.strokeStyle='#3b6f9d';ctx.lineWidth=2*d;ctx.beginPath();for(let f=0;f<=state.duration;f+=.5){const v=valueAt(state.selected,ch,f),x=X(f),y=Y(v);if(f===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();for(const k of tr){ctx.fillStyle=k.f===state.frame?'#ffd166':'#69b4ff';ctx.beginPath();ctx.arc(X(k.f),Y(k.v),4*d,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#aaa';ctx.fillText(`Frame 0`,L,h-6*d);ctx.fillText(`Frame ${state.duration}`,w-55*d,h-6*d);}
function keyListDraw(){const host=$('#keyList'),ch=$('#curveChannel').value||'rz',tr=getTrack(state.selected,ch)||[];host.innerHTML='';tr.forEach((k,idx)=>{const r=document.createElement('div');r.className='keyRow';r.innerHTML=`<input type="number" value="${k.f}" min="0" max="${state.duration}"><input type="number" value="${k.v}" step="0.1"><select><option smooth>Smooth</option><option corner>Corner</option><option linear>Linear</option><option step>Step</option></select><button>×</button>`;const [fi,vi,se,del]=r.children;se.value=k.type||'smooth';fi.onchange=()=>{pushUndo();k.f=clamp(parseInt(fi.value)||0,0,state.duration);tr.sort((a,b)=>a.f-b.f);syncAutoRangeEnd();timelineDraw();curveDraw();keyListDraw();};vi.onchange=()=>{pushUndo();k.v=parseFloat(vi.value)||0;timelineDraw();curveDraw();render();};se.onchange=()=>{pushUndo();k.type=se.value;curveDraw();render();};del.onclick=()=>{pushUndo();tr.splice(idx,1);syncAutoRangeEnd();timelineDraw();curveDraw();keyListDraw();render();};host.appendChild(r);});if(!tr.length)host.innerHTML='<div class="muted">Bu kanalda key yok.</div>';}

// ---------- presets ----------
function clearPose(clearTracks=true){if(clearTracks)state.tracks={};for(const p of Object.values(parts)){p.base={pos:[0,0,0],rot:[0,0,0],scale:[1,1,1]};p.pivot=[...p.defaultPivot];p.parent=p.defaultParent;p.visible=p.defaultVisible!==false;}}
function restPreset(){pushUndo();clearPose(true);state.duration=72;setFrame(0);syncAllUI();render();}
function tPosePreset(){pushUndo();clearPose(true);setFrame(0);syncAllUI();render();status('Anim8or Figure bind/T-pose geri yüklendi.');}
function wavePreset(){pushUndo();clearPose(true);state.duration=40;const set=(n,p,arr)=>{for(const [f,v,t='smooth'] of arr)setKey(n,p,f,v,t,true);};set('RArm1','rz',[[0,0],[6,-88],[32,-88],[40,0]]);set('RArm1','rx',[[0,0],[6,-5],[32,-5],[40,0]]);set('RArm2','rz',[[0,0],[6,-10],[10,20],[14,-20],[18,20],[22,-20],[26,20],[30,-12],[34,0],[40,0]]);set('RHand','rz',[[0,0],[6,8],[10,-15],[14,15],[18,-15],[22,15],[26,-15],[30,10],[34,0],[40,0]]);set('Head','rz',[[0,0],[8,2],[16,-1.5],[24,2],[32,0],[40,0]]);state.frame=0;$('#rangeStart').value=0;$('#rangeEnd').value=40;syncAllUI();setFrame(0);}

// ---------- render helpers/export ----------
function hexToRgb(h){const v=parseInt(h.slice(1),16);return [((v>>16)&255)/255,((v>>8)&255)/255,(v&255)/255];}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},1000);}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
