function capture2D(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.clearRect(0,0,w,h);x.drawImage(canvas,0,0,w,h);let img=x.getImageData(0,0,w,h);processPixels(img);x.putImageData(img,0,0);return c;}
