async function exportCurrentPNG(){status('PNG render alınıyor...');await withExportCanvas(async(w,h)=>{render({frame:state.frame});await wait(20);const c=capture2D(w,h),blob=await canvasBlob(c);downloadBlob(blob,`${$('#exportPrefix').value||'Baldi'}${pad4(state.frame)}.png`);});status('PNG hazır.');}
