async function exportSheet(){const frames=frameRange(),cols=Math.max(1,parseInt($('#sheetCols').value)||6);status('Sprite sheet hazırlanıyor...');await withExportCanvas(async(w,h)=>{const rows=Math.ceil(frames.length/cols),sheet=document.createElement('canvas');sheet.width=w*cols;sheet.height=h*rows;const ctx=sheet.getContext('2d');for(let i=0;i<frames.length;i++){render({frame:frames[i]});gl.finish();const c=capture2D(w,h);ctx.drawImage(c,(i%cols)*w,Math.floor(i/cols)*h);status(`Sheet ${i+1}/${frames.length}`);await wait(0);}const b=await canvasBlob(sheet);downloadBlob(b,`${$('#exportPrefix').value||'Baldi'}_sheet.png`);});status('Sprite sheet hazır.');}
