function cleanMaterialForSave(mt){const o={};for(const [k,v] of Object.entries(mt||{}))if(k!=='textureObj'&&k!=='_textureIndex')o[k]=v;return o;}
function saveProject(){const partData={};for(const [n,p] of Object.entries(parts)){partData[n]={parent:p.parent,visible:p.visible,pivot:p.pivot,base:p.base,appearance:ensureAppearance(p),custom:!!p.custom,imported:!!p.imported,sourceType:p.sourceType||'an8',defaultParent:p.defaultParent,defaultPivot:p.defaultPivot,defaultVisible:p.defaultVisible};if(p.custom)partData[n].meshes=p.meshes;}const mats={};for(const [id,mt] of Object.entries(runtimeMaterials))if(mt.custom)mats[id]=cleanMaterialForSave(mt);const data={format:'BaldiAnimStudioProject',version:2,source:model.source,fps:state.fps,duration:state.duration,tracks:state.tracks,parts:partData,materials:mats,camera:state.camera,light:state.light};downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'baldi_animation_project.json');}
async function loadProjectFile(file){try{const o=JSON.parse(await file.text());if(o.format!=='BaldiAnimStudioProject')throw new Error('Geçersiz proje');pushUndo();for(const n of Object.keys(parts))if(parts[n].custom){delete parts[n];delete state.tracks[n];}for(const id of Object.keys(runtimeMaterials))if(runtimeMaterials[id]?.custom)delete runtimeMaterials[id];for(const [id,mt] of Object.entries(o.materials||{})){runtimeMaterials[id]=deepClone(mt);if(mt.textureDataUrl)await ensureMaterialTexture(runtimeMaterials[id]);}state.tracks=deepClone(o.tracks||{});state.fps=o.fps||24;state.duration=o.duration||72;const deferred=[];for(const [n,sp] of Object.entries(o.parts||{})){if(sp.custom){const cp=addRuntimePart(n,{parent:'Root',pivot:sp.pivot||[0,0,0],meshes:deepClone(sp.meshes||[]),sourceType:sp.sourceType||'primitive',imported:!!sp.imported,appearance:deepClone(sp.appearance||null)});Object.assign(cp,{visible:sp.visible!==false,base:deepClone(sp.base||cp.base),defaultParent:sp.defaultParent||sp.parent||'Root',defaultPivot:deepClone(sp.defaultPivot||sp.pivot||cp.pivot),defaultVisible:sp.defaultVisible!==false});deferred.push([cp,sp.parent]);}else if(parts[n]){parts[n].parent=sp.parent||parts[n].defaultParent;parts[n].visible=sp.visible!==false;parts[n].pivot=deepClone(sp.pivot||parts[n].defaultPivot);parts[n].base=deepClone(sp.base||{pos:[0,0,0],rot:[0,0,0],scale:[1,1,1]});parts[n].appearance=deepClone(sp.appearance||{tint:'#ffffff',mix:0,brightness:1,opacity:1});}}for(const [cp,par] of deferred)cp.parent=par&&parts[par]?par:'Root';if(o.camera)state.camera=deepClone(o.camera);if(o.light)state.light=deepClone(o.light);state.selected=parts[state.selected]?state.selected:(parts.Body?'Body':Object.keys(parts)[0]);syncAllUI();setFrame(0);status(`Proje yüklendi${o.version>=2?' (özel mesh/GLB dahil)':''}.`);}catch(e){console.error(e);alert('Proje açılamadı: '+e.message);}}

