let playStart=0,playBase=0,raf=0;
function togglePlay(){
  state.playing=!state.playing;
  $('#playBtn').textContent=state.playing?'❚❚':'▶';
  if(state.playing){playStart=performance.now();playBase=Number(state.frame)||0;raf=requestAnimationFrame(playTick);}
  else{cancelAnimationFrame(raf);setFrame(state.frame);}
}
function playTick(t){
  if(!state.playing)return;
  let f=playBase+(t-playStart)/1000*state.fps;
  if(f>state.duration){
    if(state.loop){const span=Math.max(1e-9,state.duration);f=f%span;playStart=t-(f/state.fps)*1000;playBase=0;}
    else{state.frame=state.duration;$('#frameInput').value=state.duration;$('#framePill').textContent='F '+state.duration;timelineDraw();render({frame:state.duration});state.playing=false;$('#playBtn').textContent='▶';return;}
  }
  // Preview frame'i integer'a KESME. Blockbench gibi ekran yenileme hızında sürekli örnekle.
  // Keyframeler yine tam frame'lerde durur; yalnızca oynatma sırasında ara değerler gerçek zamanlıdır.
  state.frame=f;
  const shown=Math.round(f*100)/100;
  $('#frameInput').value=shown;
  $('#framePill').textContent='F '+shown.toFixed(shown%1?2:0);
  syncInspector();
  timelineDraw();
  render({frame:f});
  raf=requestAnimationFrame(playTick);
}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const k=e.key.toLowerCase(),ctrl=e.ctrlKey||e.metaKey;if(ctrl&&k==='z'){e.preventDefault();undo();return;}if((ctrl&&k==='y')||(ctrl&&e.shiftKey&&k==='z')){e.preventDefault();redo();return;}if(ctrl&&k==='c'&&(state.timelineSelection.size||currentFrameChannelKeys().length)){e.preventDefault();copySelectedKeys();return;}if(ctrl&&k==='x'&&state.timelineSelection.size){e.preventDefault();if(copySelectedKeys())deleteSelectedTimelineKeys();return;}if(ctrl&&k==='v'&&state.timelineClipboard){e.preventDefault();pasteSelectedKeys();return;}if(ctrl&&k==='a'&&document.activeElement===tl){e.preventDefault();selectAllTimelineKeys();return;}if((e.key==='Delete'||e.key==='Backspace')&&state.timelineSelection.size){e.preventDefault();deleteSelectedTimelineKeys();return;}if(e.code==='Space'){e.preventDefault();togglePlay();}else if(e.key==='ArrowLeft')setFrame(state.frame-1);else if(e.key==='ArrowRight')setFrame(state.frame+1);else if(e.key==='PageUp')panTimelineFrames(-timelineVisibleSpan(tl.getBoundingClientRect().width)*.8);else if(e.key==='PageDown')panTimelineFrames(timelineVisibleSpan(tl.getBoundingClientRect().width)*.8);else if(k==='g')setTool('move');else if(k==='r')setTool('rotate');else if(k==='s')setTool('scale');else if(k==='q'||k==='escape')setTool('select');else if(k==='k')keyAll();});
